Start digging into this again, realized I forgot an important piece of information. I was using a snake_case naming strategy that interferes with typeorm's use of underscores in it's queries

```

function snakeCase(str: string) {
    return str
        .replace(/(?:([a-z])([A-Z]))|(?:((?!^)[A-Z])([a-z]))/g, "$1_$3$2$4")
        .toLowerCase();
}

export class SnakeCaseNamingStrategy extends DefaultNamingStrategy {
    tableName(targetName: string, userSpecifiedName: string) {
        return userSpecifiedName ? userSpecifiedName : snakeCase(targetName);
    }

    columnName(
        propertyName: string,
        customName: string,
        embeddedPrefixes: any
    ) {
        return snakeCase(
            embeddedPrefixes
                .concat(customName ? customName : propertyName)
                .join("_")
        );
    }

    columnNameCustomized(customName: string) {
        return customName;
    }

    relationName(propertyName: string) {
        return snakeCase(propertyName);
    }
}
```

